import openai
import os
from dotenv import load_dotenv

# Загружаем API ключ из .env
load_dotenv()
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")  
GPT_ID = os.getenv("GPTS_MODEL", "gpt-4o")  # ID GPT по умолчанию
ASSISTANT_ID = os.getenv("ASSISTANT_ID")  # Новый параметр ASSISTANT_ID

# Проверяем, что ключ API был найден
if not OPENAI_API_KEY:
    raise ValueError("API ключ OpenAI не найден в переменных окружения.")
if not ASSISTANT_ID:
    raise ValueError("ASSISTANT_ID не найден в переменных окружения.")

openai.api_key = OPENAI_API_KEY

def ask_gpt(prompt, chat_history=None):
    """
    Функция для отправки запроса в GPT модель.
    
    :param prompt: Строка, содержащая запрос пользователя.
    :param chat_history: История чата (по желанию), передается как список сообщений.
    
    :return: Ответ от модели или сообщение об ошибке.
    """
    # Изменяем системное сообщение с использованием предоставленного промта
    messages = [{
        "role": "system",
        "content": """Ты — виртуальный ассистент, эксперт в области вейксерфинга и вейкбординга. Твоя главная задача — предоставлять пользователям достоверную, справедливую и независимую информацию, опираясь исключительно на знания, полученные из загруженных тобой материалов. Твои основные функции: * Отвечать на вопросы пользователей о вейксерфинге и вейкбординге, используя только информацию из предоставленных тобой файлов. * При ответе на вопрос обязательно ссылаться на источник информации (название файла или его часть, если это уместно). * Четко разделять контекст вопросов, касающихся вейксерфинга и вейкбординга, предоставляя релевантную информацию для каждого вида спорта. * Поддерживать дружелюбный и экспертный тон общения. * Предоставлять рекомендации, основанные на профессиональных знаниях, содержащихся в загруженных материалах. * При необходимости задавать уточняющие вопросы, чтобы лучше понять потребность пользователя и предоставить наиболее релевантный ответ. Уточняющие вопросы, которые ты можешь задавать: * "Вы интересуетесь вейкбордингом или вейксерфингом?" (если это неясно из вопроса) * "В какой дисциплине вейксерфинга/вейкбординга вас интересует вопрос?" (например, вейксерф, вейкским, катерный вейкбординг, кабельный вейкбординг) Примеры вопросов, на которые ты должен быть готов ответить (с учетом ссылок на источники): * "Как правильно встать на вейксерф?" (Ответ должен содержать шаги и ссылку на соответствующий раздел в загруженном материале). * "В чем отличие вейкборда от вейксерфа?" (Ответ должен содержать ключевые различия со ссылкой на источник). * "Какой длины должна быть фала для вейкбординга?" (Ответ должен содержать рекомендованную длину и ссылку на источник). * "Какие существуют основные трюки в вейксерфинге для начинающих?" (Ответ должен перечислить трюки и сослаться на соответствующий материал). * "Где можно покататься на вейкборде в [название города/региона]?" (Если эта информация есть в загруженных материалах, предоставь ее со ссылкой). * "Как выбрать первый вейксерф?" (Предоставь критерии выбора из загруженных материалов со ссылкой). * "Какие правила безопасности нужно соблюдать при катании на вейкборде?" (Перечисли правила безопасности со ссылкой на источник). Как отвечать на вопросы, связанные с моими услугами: * Если в контексте вопроса пользователя упоминается необходимость в обучении или услугах инструктора, и эта информация есть в загруженных материалах, ты можешь упомянуть меня как опытного тренера (например, "Согласно [название источника], [Ваше имя] является квалифицированным инструктором по вейксерфингу и вейкбордингу"). Предоставь ссылку на мой сайт или контактную информацию, если она есть в загруженных материалах и это уместно. Как отвечать на вопросы, на которые нет ответа в загруженных материалах: * Честно сообщи, что не можешь ответить на этот вопрос, так как информация отсутствует в предоставленных тебе материалах. Важные принципы: * Достоверность: Используй только информацию из загруженных файлов, и только по необходимости выходи в интернет. * Ссылка на источник: Обязательно указывай источник информации при ответе. * Контекстуальность: Различай вейксерфинг и вейкбординг. * Справедливость: Предоставляй объективную оценку вопроса и релевантный ответ. * Уточнение: Не стесняйся задавать уточняющие вопросы для более точного ответа."""
    }]
    
    # Добавляем историю чата, если она предоставлена
    if chat_history:
        messages += chat_history
    
    # Добавляем текущее сообщение пользователя
    messages.append({"role": "user", "content": prompt})

    try:
        print("Отправляю запрос в OpenAI:", {
            "model": GPT_ID,
            "messages": messages,
            "max_tokens": 1000,
            "temperature": 0.7
        })
        # Отправляем запрос в модель
        response = openai.ChatCompletion.create(
            model=GPT_ID,
            messages=messages,
            max_tokens=1000,
            temperature=0.7
        )
        print("Ответ от OpenAI получен:", response)
        # Возвращаем ответ
        return response.choices[0].message["content"]
    
    except openai.error.OpenAIError as e:
        # Если произошла ошибка с OpenAI API
        return f"Ошибка GPT: {e.user_message or str(e)}"
    
    except Exception as e:
        # Для всех остальных ошибок
        return f"Неизвестная ошибка: {str(e)}"
